import React, { useState, useEffect } from "react";
import { Outlet, useNavigate, useLocation } from "react-router-dom";
import {
  Box,
  Drawer,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Typography,
  Divider,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Menu,
  MenuItem,
  useTheme,
  useMediaQuery,
  Avatar,
} from "@mui/material";
import {
  Dashboard,
  Settings,
  Support,
  Menu as MenuIcon,
} from "@mui/icons-material";
import logo from "../Images/BizBridge-Logo-1.png";
import { useDispatch, useSelector } from "react-redux";
import { updateUserMode } from "../redux/slices/userSlice";
import { Link } from "react-router-dom";
import GroupIcon from "@mui/icons-material/Group";
import StorefrontIcon from "@mui/icons-material/Storefront";
import LocalMallIcon from "@mui/icons-material/LocalMall";
import HubIcon from "@mui/icons-material/Hub";
import ReceiptLongIcon from "@mui/icons-material/ReceiptLong";
import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";

const drawerWidth = 230;
const sidebarItems = [
  { text: "Dashboard", icon: <Dashboard />, route: "/seller-dashboard" },
  {
    text: "Buyer Category",
    icon: <GroupIcon />,
    route: "/seller-dashboard/buyer-category",
  },
  {
    text: "Product Category",
    icon: <StorefrontIcon />,
    route: "/seller-dashboard/product-category",
  },
  {
    text: "Catalog",
    icon: <LocalMallIcon />,
    route: "/seller-dashboard/catalog",
  },
  {
    text: "Buyer Network",
    icon: <HubIcon />,
    route: "/seller-dashboard/buyer-network",
  },
  {
    text: "Orders",
    icon: <ShoppingCartIcon />,
    route: "/seller-dashboard/orders",
  },
  {
    text: "Pending Invoices",
    icon: <ReceiptLongIcon />,
    route: "/seller-dashboard/pending-invoices",
  },
  { text: "Support", icon: <Support />, route: "/seller-dashboard/support" },
];

export default function SellerDashboardLayout() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.user);
  const [mobileOpen, setMobileOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  const [isSeller, setIsSeller] = useState(
    location.pathname.toLowerCase().startsWith("/seller-dashboard")
  );

  useEffect(() => {
    setIsSeller(
      location.pathname.toLowerCase().startsWith("/seller-dashboard")
    );
  }, [location.pathname]);

  useEffect(() => {
    if (user?.mode === "seller") {
      setIsSeller(true);
    } else {
      setIsSeller(false);
    }
  }, [user]);
  const [profileMenuAnchor, setProfileMenuAnchor] = useState(null);
  const [openLogoutModal, setOpenLogoutModal] = useState(false);

  const handleProfileIconClick = (event) => {
    setProfileMenuAnchor(event.currentTarget);
  };

  const handleProfileMenuClose = () => {
    setProfileMenuAnchor(null);
  };

  const handleOpenLogoutModal = () => {
    setOpenLogoutModal(true);
    setProfileMenuAnchor(null);
  };

  const handleCloseLogoutModal = () => setOpenLogoutModal(false);

  const handleLogout = () => {
    localStorage.clear();
    setOpenLogoutModal(false);
    window.location.reload("/login");
  };
  const [viewMenuAnchor, setViewMenuAnchor] = useState(null);

  const openViewMenu = (event) => {
    setViewMenuAnchor(event.currentTarget);
  };

  const closeViewMenu = () => {
    setViewMenuAnchor(null);
  };

  const drawerContents = (
    <Box
      sx={{
        display: "flex",
        flexDirection: "column",
        // height: "100vh",
         height: "100%",
        overflow: "hidden",
      }}
    >
      {/* Top Logo Section */}
      <Box
        component={Link}
        to="/seller-dashboard"
        sx={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          px: 3,
          py: 2,
          cursor: "pointer",
          textDecoration: "none",
          flexShrink: 0,
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center" }}>
          <Box
            component="img"
            src={logo}
            sx={{
              height: 55,
              objectFit: "contain",
            }}
          />
        </Box>
      </Box>

      <Divider sx={{ flexShrink: 0 }} />

      {/* Seller View Label */}
      <Typography
        sx={{
          px: 3,
          py: 1.5,
          fontWeight: 600,
          color: "#4b4b4b",
          fontSize: 15,
          letterSpacing: 0.5,
          flexShrink: 0,
        }}
      >
        Seller View
      </Typography>

      {/* Menu Items List - Scrollable Section */}
      <Box
        sx={{
          flex: 1,
          overflowY: "auto",
          overflowX: "hidden",
        }}
      >
        <List sx={{ py: 0 }}>
          {sidebarItems.map(({ text, icon, route }) => (
            <ListItem
              button
              key={text}
              selected={location.pathname === route}
              sx={{
                py: 1,
                mx: 1,
                my: 0.5,
                borderRadius: 2,
                color: "#2e4254",
                background: location.pathname === route ? "#dae4f2" : "none",
                cursor: "pointer",
                transition: "background 0.2s, color 0.2s",

                "&:hover": {
                  background: "#3066be",
                  color: "#fff",
                  "& .MuiListItemIcon-root": {
                    color: "#fff",
                  },
                },

                fontWeight: location.pathname === route ? 700 : 600,
                maxWidth: "100%",
                overflowX: "hidden",
              }}
              onClick={() => {
                navigate(route, { replace: true });
                if (isMobile) setMobileOpen(false);
              }}
            >
              <ListItemIcon
                sx={{
                  color: location.pathname === route ? "#3066be" : "#4b4b4b",
                  minWidth: 0,
                  pr: 1,
                  transition: "color 0.2s",
                }}
              >
                {icon}
              </ListItemIcon>

              <ListItemText
                primary={text}
                primaryTypographyProps={{
                  fontWeight: location.pathname === route ? 700 : 600,
                  fontSize: 15,
                  letterSpacing: 0.2,
                  sx: {
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  },
                }}
              />
            </ListItem>
          ))}
        </List>
      </Box>

      {/* Bottom User Info - Fixed at Bottom */}
      <Box
        sx={{
          mt: "auto",
          px: 2,
          py: 2,
          borderTop: "1px solid #ededed",
          display: "flex",
          alignItems: "center",
          gap: 1.5,
          cursor: "pointer",
          background: "#fff",
          flexShrink: 0,
          minHeight: 70,
        }}
        onClick={() =>
          navigate("/seller-dashboard/settings", { replace: true })
        }
      >
        <Avatar
          alt={user.name}
          src={user.profileImage?.url || user.name}
          sx={{
            width: 38,
            height: 38,
            borderRadius: "50%",
            background: "#3066be",
            color: "#fff",
            fontWeight: 700,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 14,
            flexShrink: 0,
            "& img": {
              borderRadius: "50%",
            },
          }}
        />

        <Box sx={{ flexGrow: 1, overflow: "hidden" }}>
          <Typography
            sx={{
              fontSize: 14,
              fontWeight: 600,
              color: "#2e4254",
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
            }}
          >
            {user?.name}{" "}
          </Typography>
          <Typography
            sx={{
              fontSize: 12,
              color: "#7a869a",
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
            }}
          >
            {user?.businessName}
          </Typography>
        </Box>

        <IconButton size="small">
          <Settings sx={{ fontSize: 20, color: "#7a869a" }} />
        </IconButton>
      </Box>
    </Box>
  );

  return (
    <Box
      sx={{
        display: "flex",
        minHeight: "100vh",
        width: "100%",
        minWidth: 0,
        overflowX: "hidden",
        background: "#f2f3f7",
        boxSizing: "border-box",
      }}
    >
      <Drawer
        variant={isMobile ? "temporary" : "permanent"}
        open={isMobile ? mobileOpen : true}
        onClose={() => setMobileOpen(false)}
        ModalProps={{ keepMounted: true }}
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          "& .MuiDrawer-paper": {
            width: drawerWidth,
            boxSizing: "border-box",
            background: "#fff",
            borderRight: "1px solid #ededed",
            overflow: "hidden",
            height: "100vh",
            display: "flex",
            flexDirection: "column",
          },
        }}
      >
        {drawerContents}
      </Drawer>

      <Box
        sx={{
          flexGrow: 1,
          minHeight: "100vh",
          width: "100%",
          minWidth: 0,
          display: "flex",
          flexDirection: "column",
          boxSizing: "border-box",
          overflow: "hidden",
        }}
      >
        <Box
          sx={{
            height: 60,
            background: "#fff",
            borderBottom: "1px solid #ededed",
            display: "flex",
            alignItems: "center",
            px: { xs: 2, sm: 4 },
            position: "sticky",
            top: 0,
            zIndex: 10,
            flexShrink: 0,
          }}
        >
          {isMobile && (
            <IconButton
              color="inherit"
              edge="start"
              onClick={() => setMobileOpen(true)}
              sx={{ mr: 2 }}
              aria-label="open drawer"
              size="large"
            >
              <MenuIcon />
            </IconButton>
          )}
          {user?.name && (
            <Typography
              variant="body1"
              sx={{
                fontWeight: 600,
                whiteSpace: "nowrap",
                alignSelf: "center",
                display: { xs: "none", sm: "none", md: "flex" },
              }}
            >
              {user.name}
            </Typography>
          )}
          <Box sx={{ flexGrow: 1 }} />
          {/* View As Dropdown */}
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              mr: 2,
            }}
          >
            <Typography variant="body2" sx={{ color: "#6b7280", mr: 1 }}>
              View as:
            </Typography>

            <Button
              onClick={openViewMenu}
              sx={{
                textTransform: "none",
                fontWeight: 600,
                color: "#2563eb",
                fontSize: 14,
                px: 1,
              }}
              endIcon={<span style={{ fontSize: 16 }}>▼</span>}
            >
              {isSeller ? "Seller" : "Buyer"}
            </Button>

            <Menu
              anchorEl={viewMenuAnchor}
              open={Boolean(viewMenuAnchor)}
              onClose={closeViewMenu}
              anchorOrigin={{ vertical: "bottom", horizontal: "left" }}
              transformOrigin={{ vertical: "top", horizontal: "left" }}
            >
              <MenuItem
                selected={isSeller}
                onClick={() => {
                  setIsSeller(true);
                  dispatch(updateUserMode({ id: user._id, mode: "seller" }));
                  navigate("/seller-dashboard", { replace: true });
                  closeViewMenu();
                }}
              >
                Seller
              </MenuItem>

              <MenuItem
                selected={!isSeller}
                onClick={() => {
                  setIsSeller(false);
                  dispatch(updateUserMode({ id: user._id, mode: "buyer" }));
                  navigate("/buyer-dashboard", { replace: true });
                  closeViewMenu();
                }}
              >
                Buyer
              </MenuItem>
            </Menu>
          </Box>
          <Avatar
            alt={user.name}
            src={user.profileImage?.url || "https://via.placeholder.com/60"}
            onClick={handleProfileIconClick}
            sx={{
              width: 38,
              height: 38,
              borderRadius: "50%",
              background: "#3066be",
              color: "#fff",
              fontWeight: 700,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 14,
              flexShrink: 0,
              cursor: "pointer",
              "& img": {
                borderRadius: "50%",
              },
            }}
          />
          <Menu
            anchorEl={profileMenuAnchor}
            open={Boolean(profileMenuAnchor)}
            onClose={handleProfileMenuClose}
            anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
            transformOrigin={{ vertical: "top", horizontal: "right" }}
          >
            <MenuItem
              onClick={() => {
                handleOpenLogoutModal();
                handleProfileMenuClose();
              }}
            >
              Logout
            </MenuItem>
          </Menu>

          {/* Logout Modal */}
          <Dialog open={openLogoutModal} onClose={handleCloseLogoutModal}>
            <DialogTitle>Logout</DialogTitle>
            <DialogContent>
              <Typography>Are you sure you want to logout?</Typography>
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseLogoutModal}>Cancel</Button>
              <Button
                color="primary"
                variant="contained"
                onClick={handleLogout}
              >
                Logout
              </Button>
            </DialogActions>
          </Dialog>
        </Box>

        {/* Content */}
        <Box
          sx={{
            p: { xs: 1, sm: 2, md: 4 },
            width: "100%",
            mx: "auto",
            minHeight: "calc(100vh - 60px)",
            boxSizing: "border-box",
            overflowY: "auto",
          }}
        >
          <Outlet />
        </Box>
      </Box>
    </Box>
  );
}