import React, { useEffect, useState, useMemo } from "react";
import {
  Box,
  Typography,
  Button,
  TextField,
  Badge,
  IconButton,
  Chip,
  Paper,
  MenuItem,
  Select,
  InputAdornment,
  FormControl,
  InputLabel,
  Pagination,
  Stack,
} from "@mui/material";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";
import SearchIcon from "@mui/icons-material/Search";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import { useDispatch, useSelector } from "react-redux";
import { useLocation, useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { getProductsByConnection } from "../redux/slices/sellerProductSlice";
import { addToCart, getCart } from "../redux/slices/cartSlice";

export default function ViewProducts() {
  const dispatch = useDispatch();
  const location = useLocation();
  const navigate = useNavigate();
  const { connectionId, otherUserId } = location.state || {};
  
  const userId = useSelector((state) => state.user?.user?._id);
  const cart = useSelector((state) => state.cart?.cart);

  const {
    productsByConnection: allProducts = [],
    connectionPage,
    connectionTotalPages,
    connectionTotalProducts,
    loading,
    error
  } = useSelector((state) => state.products);

  const [quantities, setQuantities] = useState({});
  const [localCartCount, setLocalCartCount] = useState(0);
  const [filter, setFilter] = useState("All");
  const [searchQuery, setSearchQuery] = useState("");
  
  // Pagination states
  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(10);
  const [searchMode, setSearchMode] = useState(false);

  // Fetch products when pagination changes (server-side)
  useEffect(() => {
    if (connectionId && otherUserId && !searchMode) {
      dispatch(getProductsByConnection({ 
        connectionId, 
        otherUserId,
        page,
        limit 
      }));
    }
  }, [dispatch, connectionId, otherUserId, page, limit, searchMode]);

  // Reset to server-side mode when search is cleared
  useEffect(() => {
    if (!searchQuery.trim()) {
      setSearchMode(false);
      setPage(1);
      
      if (searchMode) {
        dispatch(getProductsByConnection({ 
          connectionId, 
          otherUserId,
          page: 1,
          limit 
        }));
      }
    }
  }, [searchQuery, searchMode, connectionId, otherUserId, dispatch, limit]);

  // Handle page change
  const handlePageChange = (event, value) => {
    setPage(value);
  };

  // Handle limit change
  const handleLimitChange = (event) => {
    const newLimit = parseInt(event.target.value);
    setLimit(newLimit);
    setPage(1);
  };

  // Handle search
  const handleSearch = () => {
    if (searchQuery.trim()) {
      setSearchMode(true);
      setPage(1);
    } else {
      setSearchMode(false);
      setPage(1);
    }
  };

  // Clear search
  const handleClearSearch = () => {
    setSearchQuery("");
    setSearchMode(false);
    setPage(1);
    
    if (connectionId && otherUserId) {
      dispatch(getProductsByConnection({ 
        connectionId, 
        otherUserId,
        page: 1,
        limit 
      }));
    }
  };

  // Handle Enter key for search
  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  // Quantity Change
  const handleQtyChange = (id, value) => {
    if (value < 0) return;
    setQuantities({ ...quantities, [id]: value });
  };

  // ADD All to Cart
  const handleAddAll = async () => {
    // Get products from current view (search results or all products)
    const currentProducts = displayProducts; // FIXED HERE
    
    const items = Object.entries(quantities)
      .filter(([id, qty]) => {
        const productExists = currentProducts?.some(p => p._id === id);
        return qty > 0 && productExists;
      })
      .map(([id, qty]) => ({
        productId: id,
        quantity: qty,
      }));

    if (items?.length === 0)
      return toast.info("Please enter quantity for at least one product.");

    try {
      await dispatch(addToCart({ userId, items })).unwrap();
      toast.success("Products added to cart!");
      const addedProductCount = items.length;
      setLocalCartCount((prev) => prev + addedProductCount);
      const sellerIds = [
        ...new Set(allProducts?.map((p) => p.user?._id).filter(Boolean)),
      ];
      await Promise.all(
        sellerIds?.map((sellerId) =>
          dispatch(getCart({ userId, seller: sellerId })).unwrap()
        )
      );

      setQuantities({});
    } catch (error) {
      toast.error("Failed to add items to cart");
    }
  };

  // Extract seller & buyer categories
  const sellerIds = useMemo(
    () => [...new Set(allProducts?.map((p) => p.user?._id).filter(Boolean))],
    [allProducts]
  );

  const buyerCategories = useMemo(
    () => [
      ...new Set(
        allProducts
          ?.flatMap((p) => p.productVisibility?.map((v) => v.buyerCategory))
          .filter(Boolean)
      ),
    ],
    [allProducts]
  );

  useEffect(() => {
    if (userId && sellerIds.length > 0) {
      dispatch(getCart({ userId, seller: sellerIds, buyerCategories }));
    }
  }, [dispatch, userId, sellerIds, buyerCategories]);

  // PRODUCT CATEGORIES FOR FILTER
  const productCategories = [
    { key: "All", label: "All Products" },
    ...Array.from(
      new Set(allProducts?.map((p) => p.category?.name).filter(Boolean))
    ).map((cat) => ({ key: cat, label: cat })),
  ];

  // CLIENT-SIDE SEARCH AND FILTER LOGIC
  const filteredProducts = useMemo(() => {
    if (!allProducts || allProducts.length === 0) return [];
    
    let result = [...allProducts];
    
    if (filter !== "All") {
      result = result.filter(p => p.category?.name === filter);
    }
    
    if (searchMode && searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter((p) => {
        return (
          p.name?.toLowerCase().includes(query) ||
          p.description?.toLowerCase().includes(query) ||
          p.category?.name?.toLowerCase().includes(query)
        );
      });
    }
    
    return result;
  }, [allProducts, filter, searchMode, searchQuery]);

  // Server-side paginated products
  const serverPaginatedProducts = useMemo(() => {
    return allProducts || [];
  }, [allProducts]);

  // Client-side paginated products (for search mode)
  const clientPaginatedProducts = useMemo(() => {
    if (!searchMode || !searchQuery.trim()) return [];
    
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    return filteredProducts.slice(startIndex, endIndex);
  }, [filteredProducts, searchMode, searchQuery, page, limit]);

  // Determine which products to display
  const displayProducts = searchMode ? clientPaginatedProducts : serverPaginatedProducts;

  // Calculate total pages
  const totalPages = useMemo(() => {
    if (searchMode) {
      return Math.ceil(filteredProducts.length / limit) || 1;
    }
    return connectionTotalPages || 1;
  }, [searchMode, filteredProducts.length, limit, connectionTotalPages]);

  // Calculate total products count
  const totalProductsCount = useMemo(() => {
    if (searchMode) {
      return filteredProducts.length;
    }
    return connectionTotalProducts || 0;
  }, [searchMode, filteredProducts.length, connectionTotalProducts]);

  // Current page number
  const currentPage = page;

  // Total Cart Count
  const totalCartCount = useMemo(() => {
    const backendCount = Array.isArray(cart) ? cart.length : 0;
    return backendCount + localCartCount;
  }, [cart, localCartCount]);

  return (
    <Box
      sx={{
        px: { xs: 2, md: 4 },
        py: 3,
        backgroundColor: "#f5f7fa",
        minHeight: "100vh",
      }}
    >
      <Typography fontWeight={700} fontSize={26} sx={{ mb: 3 }}>
        View Products
      </Typography>

      {/* Filters Section */}
      <Box
        sx={{
          display: "flex",
          flexDirection: { xs: "column", md: "row" },
          gap: 3,
          mb: 3,
          alignItems: { xs: "stretch", md: "center" },
        }}
      >
        {/* Search Field */}
        <Box sx={{ flex: 1 }}>
          <TextField
            fullWidth
            placeholder="Search products by name, description, or category..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={handleKeyPress}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              ),
              endAdornment: (
                <InputAdornment position="end">
                  {searchQuery && (
                    <IconButton
                      size="small"
                      onClick={handleClearSearch}
                      sx={{ p: 0.5, mr: 1 }}
                    >
                      <Typography variant="caption" color="textSecondary">
                        Clear
                      </Typography>
                    </IconButton>
                  )}
                  <Button
                    variant="contained"
                    size="small"
                    onClick={handleSearch}
                    disabled={!searchQuery.trim()}
                    sx={{
                      minWidth: '80px',
                      backgroundColor: '#fb8900',
                      '&:hover': { backgroundColor: '#fb8a00e2' },
                      '&.Mui-disabled': {
                        backgroundColor: '#f0f0f0',
                        color: '#aaa',
                      }
                    }}
                  >
                    Search
                  </Button>
                </InputAdornment>
              ),
            }}
            sx={{
              backgroundColor: "white",
              borderRadius: 1,
              "& .MuiOutlinedInput-root": {
                borderRadius: 2,
              },
            }}
            size="small"
          />
        </Box>

        {/* Category Dropdown */}
        <Box sx={{ minWidth: 200 }}>
          <FormControl fullWidth size="small">
            <InputLabel id="category-select-label">Category</InputLabel>
            <Select
              labelId="category-select-label"
              id="category-select"
              value={filter}
              label="Category"
              onChange={(e) => setFilter(e.target.value)}
              sx={{
                backgroundColor: "white",
                borderRadius: 2,
              }}
              MenuProps={{
                PaperProps: {
                  sx: {
                    maxHeight: 300,
                  },
                },
              }}
              IconComponent={ExpandMoreIcon}
            >
              {productCategories.map((category) => (
                <MenuItem key={category.key} value={category.key}>
                  {category.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Box>

        {/* Items per page selector */}
        <Box sx={{ minWidth: 120 }}>
          <FormControl fullWidth size="small">
            <InputLabel id="limit-select-label">Items</InputLabel>
            <Select
              labelId="limit-select-label"
              value={limit.toString()}
              label="Items"
              onChange={handleLimitChange}
              sx={{
                backgroundColor: "white",
                borderRadius: 2,
              }}
            >
              <MenuItem value="10">10 per page</MenuItem>
              <MenuItem value="20">20 per page</MenuItem>
              <MenuItem value="50">50 per page</MenuItem>
              <MenuItem value="100">100 per page</MenuItem>
            </Select>
          </FormControl>
        </Box>
      </Box>

      {/* Active Filters Display */}
      {(filter !== "All" || searchMode) && (
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 1,
            flexWrap: "wrap",
            mb: 2,
          }}
        >
          <Typography variant="body2" color="textSecondary">
            Active filters:
          </Typography>
          {filter !== "All" && (
            <Chip
              label={`Category: ${filter}`}
              size="small"
              onDelete={() => setFilter("All")}
              sx={{ fontSize: "0.75rem" }}
            />
          )}
          {searchMode && searchQuery && (
            <Chip
              label={`Search: "${searchQuery}" (${filteredProducts.length} found)`}
              size="small"
              onDelete={handleClearSearch}
              sx={{ fontSize: "0.75rem" }}
            />
          )}
        </Box>
      )}

      {/* Results Count */}
      {/* <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="body2" color="textSecondary">
          {loading ? (
            "Loading products..."
          ) : searchMode ? (
            `Found ${filteredProducts.length} products matching "${searchQuery}"`
          ) : (
            `Showing ${displayProducts.length} of ${totalProductsCount} products`
          )}
        </Typography>
        
        <Typography variant="body2" color="textSecondary">
          Page {currentPage} of {totalPages}
          {searchMode && " (Client-side search)"}
        </Typography>
      </Box> */}

      {/* Loading State */}
      {loading && displayProducts.length === 0 && (
        <Box sx={{ textAlign: 'center', py: 4 }}>
          <Typography>Loading products...</Typography>
        </Box>
      )}

      {/* Error State */}
      {error && !loading && (
        <Box sx={{ textAlign: 'center', py: 4, color: 'error.main' }}>
          <Typography>Error: {error}</Typography>
        </Box>
      )}

      {/* Products Table */}
      {!loading && (
        <TableContainer component={Paper} sx={{ borderRadius: 2, mb: 3 }}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell sx={{ fontWeight: 800, fontSize: "16px" }}>
                  #
                </TableCell>
                <TableCell sx={{ fontWeight: 800, fontSize: "16px" }}>
                  Name
                </TableCell>
                <TableCell sx={{ fontWeight: 800, fontSize: "16px" }}>
                  Category
                </TableCell>
                <TableCell sx={{ fontWeight: 800, fontSize: "16px" }}>
                  Price
                </TableCell>
                <TableCell
                  sx={{ fontWeight: 800, fontSize: "16px", textAlign: "center" }}
                >
                  Quantity
                </TableCell>
              </TableRow>
            </TableHead>

            <TableBody>
              {displayProducts.length > 0 ? (
                displayProducts.map((product, index) => {
                  const serialNumber = (currentPage - 1) * limit + index + 1;
                  
                  return (
                    <TableRow key={product._id}>
                      <TableCell sx={{ fontSize: "15px" }}>
                        {serialNumber}
                      </TableCell>

                      <TableCell>
                        <Box
                          sx={{
                            color: "#22364a",
                            fontWeight: 600,
                            fontSize: "15px",
                            cursor: "pointer",
                            "&:hover": {
                              textDecoration: "underline",
                              color: "#fb8900",
                            },
                          }}
                          onClick={() =>
                            navigate(
                              `/buyer-dashboard/product-details/${product._id}`,
                              { state: { product } }
                            )
                          }
                        >
                          {product.name}
                        </Box>
                      </TableCell>

                      <TableCell sx={{ fontSize: "14px", color: "#555" }}>
                        {product.category?.name || "Uncategorized"}
                      </TableCell>

                      <TableCell
                        sx={{ fontSize: "15px", color: "#fb8900", fontWeight: 700 }}
                      >
                        ₹{product.price}
                      </TableCell>

                      <TableCell sx={{ textAlign: "center" }}>
                        <TextField
                          type="number"
                          size="small"
                          value={quantities[product._id] || 0}
                          onChange={(e) =>
                            handleQtyChange(
                              product._id,
                              parseInt(e.target.value) || 0
                            )
                          }
                          sx={{
                            width: "70px",
                            "& .MuiInputBase-root": {
                              borderRadius: "8px",
                              backgroundColor: "#f0f0f0",
                            },
                          }}
                        />
                      </TableCell>
                    </TableRow>
                  );
                })
              ) : (
                <TableRow>
                  <TableCell colSpan={5} sx={{ textAlign: "center", py: 4 }}>
                    <Typography color="textSecondary">
                      {searchMode && searchQuery
                        ? `No products found matching "${searchQuery}"`
                        : "No products available"}
                    </Typography>
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {/* Pagination */}
      {totalPages > 1 && !loading && (
        <Box sx={{ display: 'flex', justifyContent: 'center', mb: 3 }}>
          <Stack spacing={2}>
            <Pagination
              count={totalPages}
              page={currentPage}
              onChange={handlePageChange}
              color="primary"
              size="large"
              showFirstButton
              showLastButton
              siblingCount={1}
              boundaryCount={1}
              sx={{
                '& .MuiPaginationItem-root': {
                  fontWeight: 600,
                },
                '& .Mui-selected': {
                  backgroundColor: '#fb8900 !important',
                  color: 'white',
                }
              }}
            />
          </Stack>
        </Box>
      )}

      {/* Bottom Buttons */}
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexDirection: { xs: "column", md: "row" },
          gap: 2,
        }}
      >
        <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>
          <Button
            variant="contained"
            onClick={handleAddAll}
            disabled={displayProducts.length === 0}
            sx={{
              px: 4,
              py: 1.5,
              borderRadius: 3,
              fontWeight: 600,
              backgroundColor: "#fb8900",
              color: "#fff",
              "&:hover": { backgroundColor: "#fb8a00e2" },
              "&.Mui-disabled": {
                backgroundColor: "#f0f0f0",
                color: "#aaa",
              },
            }}
          >
            Add to Cart
          </Button>

          <Badge
            badgeContent={totalCartCount}
            color="primary"
            anchorOrigin={{ vertical: "top", horizontal: "right" }}
          >
            <IconButton
              onClick={() => {
                navigate("/buyer-dashboard/cart", {
                  state: { buyerCategories, sellerIds, userId },
                });
              }}
              sx={{
                backgroundColor: "#e0f2f1",
                borderRadius: "50%",
                width: 50,
                height: 50,
                color: "#22364a",
                "&:hover": { backgroundColor: "#b2dfdb" },
              }}
            >
              <ShoppingCartIcon fontSize="medium" />
            </IconButton>
          </Badge>
        </Box>

        {/* Pagination Summary */}
        {displayProducts.length > 0 && (
          <Typography variant="body2" color="textSecondary">
            Showing {(currentPage - 1) * limit + 1} to{" "}
            {Math.min(currentPage * limit, totalProductsCount)} of{" "}
            {totalProductsCount} products
          </Typography>
        )}
      </Box>
    </Box>
  );
}