import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Grid,
  TextField,
  Button,
  Switch,
  Paper,
  Tabs,
  Tab,
  useTheme,
  useMediaQuery,
  IconButton,
  InputAdornment,
  Avatar,
  Divider,
  Card,
  CardContent,
  CircularProgress,
} from "@mui/material";
import { useSelector, useDispatch } from "react-redux";
import {
  updateProfile,
  reloadUser,
  updatePassword,
  uploadProfileImage,
  deleteProfileImage,
} from "../redux/slices/userSlice";
import { toast } from "react-toastify";
import Visibility from "@mui/icons-material/Visibility";
import VisibilityOff from "@mui/icons-material/VisibilityOff";
import CameraAlt from "@mui/icons-material/CameraAlt";
import PersonOutline from "@mui/icons-material/PersonOutline";
import Business from "@mui/icons-material/Business";
import AccountBalance from "@mui/icons-material/AccountBalance";
import LockReset from "@mui/icons-material/LockReset";
import NotificationsActive from "@mui/icons-material/NotificationsActive";
import CheckCircle from "@mui/icons-material/CheckCircle";

// Import the new component
import ProfileImageUpload from "../Components/ProfileImageUpload";

export default function SettingPage() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const dispatch = useDispatch();

  const { user, operations, error } = useSelector((state) => state.user);

  // Access operations safely - FIXED ERROR HERE
  const profileUpdate = operations?.profileUpdate || {
    loading: false,
    success: false,
    error: null,
  };
  const passwordUpdate = operations?.passwordUpdate || {
    loading: false,
    success: false,
    error: null,
  };
  const imageUpload = operations?.imageUpload || {
    loading: false,
    success: false,
    error: null,
  };
  const imageDelete = operations?.imageDelete || {
    loading: false,
    success: false,
    error: null,
  };

  const [tabIndex, setTabIndex] = useState(0);

  // Password state
  const [passwordData, setPasswordData] = useState({
    currentPassword: "",
    newPassword: "",
    confirmPassword: "",
  });

  // Password visibility state
  const [showPassword, setShowPassword] = useState({
    current: false,
    new: false,
    confirm: false,
  });

  // Profile image state
  const [profileImage, setProfileImage] = useState(null);
  const [imageFile, setImageFile] = useState(null);

  // Error states
  const [formErrors, setFormErrors] = useState({});

  const [localProfile, setLocalProfile] = useState({
    name: "",
    phone: "",
    email: "",
    businessAddress: "",
    businessName: "",
    gstNumber: "",
    bankDetails: {
      bankName: "",
      accountName: "",
      accountNumber: "",
      upiId: "",
      ifscCode: "",
      branchName: "",
      branchAddress: "",
    },
  });

  const [localNotifications, setLocalNotifications] = useState({
    orderUpdates: true,
    newOffers: true,
    chatMessages: true,
  });

  // Show backend errors using toast
  useEffect(() => {
    if (profileUpdate.error) {
      toast.error(profileUpdate.error);
      dispatch({ type: "user/resetProfileUpdate" });
    }
    if (passwordUpdate.error) {
      toast.error(passwordUpdate.error);
      dispatch({ type: "user/resetPasswordUpdate" });
    }
    if (imageUpload.error) {
      toast.error(imageUpload.error);
      dispatch({ type: "user/resetImageUpload" });
    }
    if (imageDelete.error) {
      toast.error(imageDelete.error);
      dispatch({ type: "user/resetImageDelete" });
    }
    if (error) {
      toast.error(error);
    }
  }, [
    profileUpdate.error,
    passwordUpdate.error,
    imageUpload.error,
    imageDelete.error,
    error,
    dispatch,
  ]);

  // Show success messages using toast
  useEffect(() => {
    // Store previous success states to detect changes
    let mounted = true;

    // Only show toast and reset when success changes from false to true
    if (profileUpdate.success) {
      toast.success("Profile updated successfully!");
      // Reset after a small delay
      setTimeout(() => {
        if (mounted) {
          dispatch({ type: "user/resetProfileUpdate" });
        }
      }, 2000);
    }

    if (passwordUpdate.success) {
      toast.success("Password changed successfully!");
      setPasswordData({
        currentPassword: "",
        newPassword: "",
        confirmPassword: "",
      });
      setTimeout(() => {
        if (mounted) {
          dispatch({ type: "user/resetPasswordUpdate" });
        }
      }, 2000);
    }

    if (imageUpload.success) {
      toast.success("Profile image uploaded successfully!");
      // Refresh user data after a delay
      setTimeout(() => {
        if (mounted) {
          dispatch(reloadUser());
          setImageFile(null);
          dispatch({ type: "user/resetImageUpload" });
        }
      }, 2000);
    }

    if (imageDelete.success) {
      toast.success("Profile image removed successfully!");
      setProfileImage(null);
      // Refresh user data after a delay
      setTimeout(() => {
        if (mounted) {
          dispatch(reloadUser());
          dispatch({ type: "user/resetImageDelete" });
        }
      }, 2000);
    }

    return () => {
      mounted = false;
    };
  }, [
    profileUpdate.success,
    passwordUpdate.success,
    imageUpload.success,
    imageDelete.success,
    dispatch,
  ]);

  useEffect(() => {
    if (user) {
      setLocalProfile({
        name: user.name || "",
        phone: user.phone || "",
        email: user.email || "",
        businessAddress: user.businessAddress || "",
        businessName: user.businessName || "",
        gstNumber: user.gstNumber || "",
        bankDetails: {
          bankName: user.bankDetails?.bankName || "",
          accountName: user.bankDetails?.accountName || "",
          accountNumber: user.bankDetails?.accountNumber || "",
          upiId: user.bankDetails?.upiId || "",
          ifscCode: user.bankDetails?.ifscCode || "",
          branchName: user.bankDetails?.branchName || "",
          branchAddress: user.bankDetails?.branchAddress || "",
        },
      });

      // Set profile image if exists
      if (user.profileImage) {
        setProfileImage(user.profileImage);
      } else {
        setProfileImage(null);
      }
    }
  }, [user]);

  // Handle profile image change
  const handleImageChange = (file) => {
    setImageFile(file);

    // If file is null, it means remove image
    if (!file) {
      handleRemoveImage();
    }
  };

  // Handle image upload
  const handleImageUpload = async () => {
    if (!imageFile) return;

    const formData = new FormData();
    formData.append("profileImage", imageFile);

    try {
      await dispatch(uploadProfileImage(formData)).unwrap();
    } catch (error) {
      // Error handled in useEffect
    }
  };

  // Handle remove image
  const handleRemoveImage = async () => {
    try {
      await dispatch(deleteProfileImage()).unwrap();
    } catch (error) {
      // Error handled in useEffect
    }
  };

  // Auto upload image when imageFile changes
  useEffect(() => {
    if (imageFile) {
      handleImageUpload();
    }
  }, [imageFile]);

  const handleProfileChange = (field) => (e) =>
    setLocalProfile((prev) => ({ ...prev, [field]: e.target.value }));

  const handleBankChange = (field) => (e) =>
    setLocalProfile((prev) => ({
      ...prev,
      bankDetails: { ...prev.bankDetails, [field]: e.target.value },
    }));

  const handleSwitch = (name) => (e) =>
    setLocalNotifications((prev) => ({ ...prev, [name]: e.target.checked }));

  const handleProfileSave = async (e) => {
    e.preventDefault();
    setFormErrors({});

    try {
      const result = await dispatch(updateProfile(localProfile)).unwrap();
      if (result) {
        dispatch(reloadUser());
      }
    } catch (error) {
      // Error is handled by useEffect above
    }
  };

  const handlePasswordChange = (field) => (e) => {
    setPasswordData((prev) => ({ ...prev, [field]: e.target.value }));
    // Clear field-specific error
    if (formErrors[field]) {
      setFormErrors((prev) => ({ ...prev, [field]: "" }));
    }
  };

  // Toggle password visibility
  const handleClickShowPassword = (field) => {
    setShowPassword((prev) => ({
      ...prev,
      [field]: !prev[field],
    }));
  };

  const handleMouseDownPassword = (event) => {
    event.preventDefault();
  };

  const validatePasswordForm = () => {
    const errors = {};

    if (!passwordData.currentPassword.trim()) {
      errors.currentPassword = "Current password is required";
    }

    if (!passwordData.newPassword.trim()) {
      errors.newPassword = "New password is required";
    } else if (passwordData.newPassword.length < 6) {
      errors.newPassword = "Password must be at least 6 characters";
    }

    if (!passwordData.confirmPassword.trim()) {
      errors.confirmPassword = "Please confirm your password";
    } else if (passwordData.newPassword !== passwordData.confirmPassword) {
      errors.confirmPassword = "Passwords do not match";
    }

    return errors;
  };

  const handlePasswordSave = async (e) => {
    e.preventDefault();

    const errors = validatePasswordForm();
    if (Object.keys(errors).length > 0) {
      setFormErrors(errors);
      return;
    }

    try {
      await dispatch(
        updatePassword({
          oldPassword: passwordData.currentPassword,
          newPassword: passwordData.newPassword,
          confirmPassword: passwordData.confirmPassword,
        })
      ).unwrap();
    } catch (error) {
      // Error is handled by useEffect above
    }
  };

  const handleNotificationSave = (e) => {
    e.preventDefault();
    toast.success("Notification preferences updated!");
  };

  // Tab icons and labels
  const tabs = [
    { label: "Personal", icon: <PersonOutline /> },
    { label: "Business", icon: <Business /> },
    { label: "Bank", icon: <AccountBalance /> },
    { label: "Password", icon: <LockReset /> },
  ];

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        background: "linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%)",
        boxSizing: "border-box",
        display: "flex",
        justifyContent: "center",
      }}
    >
      <Box
        sx={{
          width: "100%",
          maxWidth: 1400,
          mx: "auto",
          display: "flex",
          flexDirection: "column",
          gap: 4,
        }}
      >
        {/* Header Section with Profile Image */}
        <Card
          sx={{
            borderRadius: 3,
            background: "linear-gradient(135deg, #ffffff 0%, #f8fafc 100%)",
            boxShadow: "0 8px 32px rgba(31, 38, 135, 0.08)",
            border: "1px solid rgba(255, 255, 255, 0.8)",
            overflow: "hidden",
          }}
        >
          <CardContent sx={{ p: { xs: 3, md: 5 } }}>
            <Box
              sx={{
                display: "flex",
                flexDirection: { xs: "column", md: "row" },
                alignItems: { xs: "center", md: "flex-start" },
                gap: 4,
              }}
            >
              {/* Profile Image Section */}
              <Box
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  minWidth: { xs: "100%", md: 200 },
                }}
              >
                <ProfileImageUpload
                  currentImage={profileImage?.url}
                  onImageChange={handleImageChange}
                  loading={imageUpload.loading || imageDelete.loading}
                  size={140}
                />
                <Typography
                  variant="h6"
                  fontWeight={700}
                  color="#131e32"
                  sx={{ mt: 1 }}
                >
                  {user?.name || "User"}
                </Typography>
                <Typography
                  variant="body2"
                  color="#46639c"
                  sx={{ fontWeight: 500 }}
                >
                  {user?.email || ""}
                </Typography>
              </Box>

              {/* Header Text Section */}
              <Box sx={{ flex: 1 }}>
                <Typography
                  variant={isMobile ? "h5" : "h4"}
                  fontWeight={800}
                  color="#131e32"
                  mb={1}
                  sx={{
                    background:
                      "linear-gradient(90deg, #131e32 0%, #2d3748 100%)",
                    WebkitBackgroundClip: "text",
                    WebkitTextFillColor: "transparent",
                  }}
                >
                  Account Settings
                </Typography>
                <Typography
                  variant="body1"
                  color="#46639c"
                  sx={{ mb: 3, lineHeight: 1.6, fontWeight: 500 }}
                >
                  Manage your profile information, business details, bank
                  accounts, and security settings. Keep your account up-to-date.
                </Typography>

                {/* Quick Stats */}
                <Box
                  sx={{
                    display: "flex",
                    gap: 3,
                    flexWrap: "wrap",
                    mt: 3,
                  }}
                >
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                    <CheckCircle sx={{ color: "#10b981", fontSize: 20 }} />
                    <Typography
                      variant="body2"
                      color="#46639c"
                      fontWeight={500}
                    >
                      Profile {user?.name ? "Complete" : "Incomplete"}
                    </Typography>
                  </Box>
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                    <CheckCircle
                      sx={{
                        color: user?.businessName ? "#10b981" : "#ef4444",
                        fontSize: 20,
                      }}
                    />
                    <Typography
                      variant="body2"
                      color="#46639c"
                      fontWeight={500}
                    >
                      Business {user?.businessName ? "Verified" : "Pending"}
                    </Typography>
                  </Box>
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                    <CheckCircle
                      sx={{
                        color: user?.bankDetails?.accountNumber
                          ? "#10b981"
                          : "#ef4444",
                        fontSize: 20,
                      }}
                    />
                    <Typography
                      variant="body2"
                      color="#46639c"
                      fontWeight={500}
                    >
                      Bank{" "}
                      {user?.bankDetails?.accountNumber ? "Setup" : "Not Setup"}
                    </Typography>
                  </Box>
                </Box>
              </Box>
            </Box>
          </CardContent>
        </Card>

        {/* Main Content with Tabs */}
        <Box
          sx={{
            display: "flex",
            flexDirection: { xs: "column", md: "row" },
            gap: 4,
          }}
        >
          {/* Sidebar Tabs */}
          <Card
            sx={{
              width: { xs: "100%", md: 280 },
              borderRadius: 3,
              background: "white",
              boxShadow: "0 4px 20px rgba(0,0,0,0.06)",
              border: "1px solid rgba(0,0,0,0.04)",
              height: { xs: "auto", md: "fit-content" },
              overflow: "hidden",
            }}
          >
            <Tabs
              value={tabIndex}
              onChange={(e, val) => setTabIndex(val)}
              orientation={isMobile ? "horizontal" : "vertical"}
              variant="scrollable"
              scrollButtons="auto"
              sx={{
                minHeight: { xs: "auto", md: 400 },
                "& .MuiTabs-flexContainer": {
                  gap: { xs: 1, md: 0 },
                },
                "& .MuiTab-root": {
                  textTransform: "none",
                  fontWeight: 600,
                  fontSize: "0.95rem",
                  justifyContent: isMobile ? "center" : "flex-start",
                  alignItems: "center",
                  gap: 2,
                  py: { xs: 1.5, md: 2 },
                  px: 3,
                  minHeight: { xs: 48, md: 56 },
                  color: "#64748b",
                  "&.Mui-selected": {
                    color: "#f97316",
                    backgroundColor: "rgba(249, 115, 22, 0.08)",
                    borderRight: isMobile ? "none" : "3px solid #f97316",
                    borderBottom: isMobile ? "3px solid #f97316" : "none",
                  },
                  "&:hover": {
                    backgroundColor: "rgba(249, 115, 22, 0.04)",
                  },
                },
                "& .MuiTabs-indicator": {
                  display: "none",
                },
              }}
            >
              {tabs.map((tab, index) => (
                <Tab
                  key={index}
                  icon={tab.icon}
                  iconPosition="start"
                  label={tab.label}
                  sx={{
                    borderRadius: 1,
                    mx: { xs: 0.5, md: 1 },
                    my: { xs: 0, md: 0.5 },
                  }}
                />
              ))}
            </Tabs>
          </Card>

          <Box sx={{ flex: 1 }}>
            {tabIndex === 0 && (
              <Card
                sx={{
                  borderRadius: 3,
                  background: "white",
                  boxShadow: "0 4px 20px rgba(0,0,0,0.06)",
                  border: "1px solid rgba(0,0,0,0.04)",
                  overflow: "hidden",
                }}
              >
                <CardContent sx={{ p: { xs: 3, md: 5 } }}>
                  <Typography
                    variant="h5"
                    fontWeight={700}
                    color="#131e32"
                    mb={1}
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      gap: 2,
                    }}
                  >
                    <PersonOutline />
                    Personal Profile
                  </Typography>
                  <Typography
                    variant="body2"
                    color="#46639c"
                    sx={{ mb: 4, fontWeight: 500 }}
                  >
                    Update your personal information and contact details
                  </Typography>

                  <Box
                    component="form"
                    onSubmit={handleProfileSave}
                    autoComplete="off"
                  >
                    <Grid container spacing={3}>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="Full Name"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile.name}
                          onChange={handleProfileChange("name")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="Phone Number"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile.phone}
                          onChange={handleProfileChange("phone")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          label="Email Address"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile.email}
                          onChange={handleProfileChange("email")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                    </Grid>

                    <Button
                      type="submit"
                      variant="contained"
                      sx={{
                        mt: 4,
                        px: 5,
                        py: 1.5,
                        fontWeight: 700,
                        borderRadius: 2,
                        background:
                          "linear-gradient(90deg, #f97316 0%, #fb923c 100%)",
                        textTransform: "none",
                        fontSize: "1rem",
                        boxShadow: "0 4px 12px rgba(249, 115, 22, 0.3)",
                        "&:hover": {
                          background:
                            "linear-gradient(90deg, #ea580c 0%, #f97316 100%)",
                          boxShadow: "0 6px 16px rgba(249, 115, 22, 0.4)",
                        },
                      }}
                      disabled={profileUpdate.loading}
                      startIcon={profileUpdate.loading ? null : <CheckCircle />}
                    >
                      {profileUpdate.loading ? (
                        <>
                          <CircularProgress
                            size={20}
                            sx={{ mr: 1, color: "white" }}
                          />
                          Saving...
                        </>
                      ) : (
                        "Save Personal Details"
                      )}
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            )}

            {tabIndex === 1 && (
              <Card
                sx={{
                  borderRadius: 3,
                  background: "white",
                  boxShadow: "0 4px 20px rgba(0,0,0,0.06)",
                  border: "1px solid rgba(0,0,0,0.04)",
                  overflow: "hidden",
                }}
              >
                <CardContent sx={{ p: { xs: 3, md: 5 } }}>
                  <Typography
                    variant="h5"
                    fontWeight={700}
                    color="#131e32"
                    mb={1}
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      gap: 2,
                    }}
                  >
                    <Business />
                    Business Profile
                  </Typography>
                  <Typography
                    variant="body2"
                    color="#46639c"
                    sx={{ mb: 4, fontWeight: 500 }}
                  >
                    Manage your business information and registration details
                  </Typography>

                  <Box
                    component="form"
                    onSubmit={handleProfileSave}
                    autoComplete="off"
                  >
                    <Grid container spacing={3}>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="Business Name"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile.businessName}
                          onChange={handleProfileChange("businessName")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="GST Number"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile.gstNumber}
                          onChange={handleProfileChange("gstNumber")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          label="Business Address"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile.businessAddress}
                          onChange={handleProfileChange("businessAddress")}
                          multiline
                          minRows={3}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                    </Grid>

                    <Button
                      type="submit"
                      variant="contained"
                      sx={{
                        mt: 4,
                        px: 5,
                        py: 1.5,
                        fontWeight: 700,
                        borderRadius: 2,
                        background:
                          "linear-gradient(90deg, #f97316 0%, #fb923c 100%)",
                        textTransform: "none",
                        fontSize: "1rem",
                        boxShadow: "0 4px 12px rgba(249, 115, 22, 0.3)",
                        "&:hover": {
                          background:
                            "linear-gradient(90deg, #ea580c 0%, #f97316 100%)",
                          boxShadow: "0 6px 16px rgba(249, 115, 22, 0.4)",
                        },
                      }}
                      disabled={profileUpdate.loading}
                      startIcon={profileUpdate.loading ? null : <CheckCircle />}
                    >
                      {profileUpdate.loading ? (
                        <>
                          <CircularProgress
                            size={20}
                            sx={{ mr: 1, color: "white" }}
                          />
                          Saving...
                        </>
                      ) : (
                        "Save Business Details"
                      )}
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            )}

            {tabIndex === 2 && (
              <Card
                sx={{
                  borderRadius: 3,
                  background: "white",
                  boxShadow: "0 4px 20px rgba(0,0,0,0.06)",
                  border: "1px solid rgba(0,0,0,0.04)",
                  overflow: "hidden",
                }}
              >
                <CardContent sx={{ p: { xs: 3, md: 5 } }}>
                  <Typography
                    variant="h5"
                    fontWeight={700}
                    color="#131e32"
                    mb={1}
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      gap: 2,
                    }}
                  >
                    <AccountBalance />
                    Bank Details
                  </Typography>
                  <Typography
                    variant="body2"
                    color="#46639c"
                    sx={{ mb: 4, fontWeight: 500 }}
                  >
                    Update your bank account information for payments
                  </Typography>

                  <Box
                    component="form"
                    onSubmit={handleProfileSave}
                    autoComplete="off"
                  >
                    <Grid container spacing={3}>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="Bank Name"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile?.bankDetails?.bankName}
                          onChange={handleBankChange("bankName")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="Account Holder Name"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile?.bankDetails?.accountName}
                          onChange={handleBankChange("accountName")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="Account Number"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile?.bankDetails?.accountNumber}
                          onChange={handleBankChange("accountNumber")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="UPI ID"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile?.bankDetails?.upiId}
                          onChange={handleBankChange("upiId")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="IFSC Code"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile?.bankDetails?.ifscCode}
                          onChange={handleBankChange("ifscCode")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="Branch Name"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile?.bankDetails?.branchName}
                          onChange={handleBankChange("branchName")}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          label="Branch Address"
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={localProfile?.bankDetails?.branchAddress}
                          onChange={handleBankChange("branchAddress")}
                          multiline
                          minRows={2}
                          error={!!profileUpdate.error}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                        />
                      </Grid>
                    </Grid>

                    <Button
                      type="submit"
                      variant="contained"
                      sx={{
                        mt: 4,
                        px: 5,
                        py: 1.5,
                        fontWeight: 700,
                        borderRadius: 2,
                        background:
                          "linear-gradient(90deg, #f97316 0%, #fb923c 100%)",
                        textTransform: "none",
                        fontSize: "1rem",
                        boxShadow: "0 4px 12px rgba(249, 115, 22, 0.3)",
                        "&:hover": {
                          background:
                            "linear-gradient(90deg, #ea580c 0%, #f97316 100%)",
                          boxShadow: "0 6px 16px rgba(249, 115, 22, 0.4)",
                        },
                      }}
                      disabled={profileUpdate.loading}
                      startIcon={profileUpdate.loading ? null : <CheckCircle />}
                    >
                      {profileUpdate.loading ? (
                        <>
                          <CircularProgress
                            size={20}
                            sx={{ mr: 1, color: "white" }}
                          />
                          Saving...
                        </>
                      ) : (
                        "Save Bank Details"
                      )}
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            )}

            {tabIndex === 3 && (
              <Card
                sx={{
                  borderRadius: 3,
                  background: "white",
                  boxShadow: "0 4px 20px rgba(0,0,0,0.06)",
                  border: "1px solid rgba(0,0,0,0.04)",
                  overflow: "hidden",
                }}
              >
                <CardContent sx={{ p: { xs: 3, md: 5 } }}>
                  <Typography
                    variant="h5"
                    fontWeight={700}
                    color="#131e32"
                    mb={1}
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      gap: 2,
                    }}
                  >
                    <LockReset />
                    Change Password
                  </Typography>
                  <Typography
                    variant="body2"
                    color="#46639c"
                    sx={{ mb: 4, fontWeight: 500 }}
                  >
                    Update your password to keep your account secure
                  </Typography>

                  <Box
                    component="form"
                    onSubmit={handlePasswordSave}
                    autoComplete="off"
                  >
                    <Grid container spacing={3}>
                      <Grid item xs={12}>
                        <TextField
                          label="Current Password"
                          type={showPassword.current ? "text" : "password"}
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={passwordData.currentPassword}
                          onChange={handlePasswordChange("currentPassword")}
                          error={!!formErrors.currentPassword}
                          helperText={formErrors.currentPassword}
                          disabled={passwordUpdate.loading}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                          InputProps={{
                            endAdornment: (
                              <InputAdornment position="end">
                                <IconButton
                                  aria-label="toggle password visibility"
                                  onClick={() =>
                                    handleClickShowPassword("current")
                                  }
                                  onMouseDown={handleMouseDownPassword}
                                  edge="end"
                                  size="small"
                                >
                                  {showPassword.current ? (
                                    <VisibilityOff />
                                  ) : (
                                    <Visibility />
                                  )}
                                </IconButton>
                              </InputAdornment>
                            ),
                          }}
                        />
                      </Grid>

                      <Grid item xs={12} md={6}>
                        <TextField
                          label="New Password"
                          type={showPassword.new ? "text" : "password"}
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={passwordData.newPassword}
                          onChange={handlePasswordChange("newPassword")}
                          error={!!formErrors.newPassword}
                          helperText={formErrors.newPassword}
                          disabled={passwordUpdate.loading}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                          InputProps={{
                            endAdornment: (
                              <InputAdornment position="end">
                                <IconButton
                                  aria-label="toggle password visibility"
                                  onClick={() => handleClickShowPassword("new")}
                                  onMouseDown={handleMouseDownPassword}
                                  edge="end"
                                  size="small"
                                >
                                  {showPassword.new ? (
                                    <VisibilityOff />
                                  ) : (
                                    <Visibility />
                                  )}
                                </IconButton>
                              </InputAdornment>
                            ),
                          }}
                        />
                      </Grid>

                      <Grid item xs={12} md={6}>
                        <TextField
                          label="Confirm New Password"
                          type={showPassword.confirm ? "text" : "password"}
                          variant="outlined"
                          size="medium"
                          fullWidth
                          value={passwordData.confirmPassword}
                          onChange={handlePasswordChange("confirmPassword")}
                          error={!!formErrors.confirmPassword}
                          helperText={formErrors.confirmPassword}
                          disabled={passwordUpdate.loading}
                          sx={{
                            "& .MuiOutlinedInput-root": {
                              borderRadius: 2,
                              "&:hover fieldset": {
                                borderColor: "#f97316",
                              },
                            },
                          }}
                          InputProps={{
                            endAdornment: (
                              <InputAdornment position="end">
                                <IconButton
                                  aria-label="toggle password visibility"
                                  onClick={() =>
                                    handleClickShowPassword("confirm")
                                  }
                                  onMouseDown={handleMouseDownPassword}
                                  edge="end"
                                  size="small"
                                >
                                  {showPassword.confirm ? (
                                    <VisibilityOff />
                                  ) : (
                                    <Visibility />
                                  )}
                                </IconButton>
                              </InputAdornment>
                            ),
                          }}
                        />
                      </Grid>
                    </Grid>

                    <Button
                      type="submit"
                      variant="contained"
                      sx={{
                        mt: 4,
                        px: 5,
                        py: 1.5,
                        fontWeight: 700,
                        borderRadius: 2,
                        background:
                          "linear-gradient(90deg, #f97316 0%, #fb923c 100%)",
                        textTransform: "none",
                        fontSize: "1rem",
                        boxShadow: "0 4px 12px rgba(249, 115, 22, 0.3)",
                        "&:hover": {
                          background:
                            "linear-gradient(90deg, #ea580c 0%, #f97316 100%)",
                          boxShadow: "0 6px 16px rgba(249, 115, 22, 0.4)",
                        },
                      }}
                      disabled={passwordUpdate.loading}
                      startIcon={
                        passwordUpdate.loading ? null : <CheckCircle />
                      }
                    >
                      {passwordUpdate.loading ? (
                        <>
                          <CircularProgress
                            size={20}
                            sx={{ mr: 1, color: "white" }}
                          />
                          Updating...
                        </>
                      ) : (
                        "Change Password"
                      )}
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            )}
          </Box>
        </Box>

        {/* Notification Settings */}
        <Card
          sx={{
            borderRadius: 3,
            background: "white",
            boxShadow: "0 4px 20px rgba(0,0,0,0.06)",
            border: "1px solid rgba(0,0,0,0.04)",
            overflow: "hidden",
          }}
        >
          <CardContent sx={{ p: { xs: 3, md: 5 } }}>
            <Typography
              variant="h5"
              fontWeight={700}
              color="#131e32"
              mb={1}
              sx={{
                display: "flex",
                alignItems: "center",
                gap: 2,
              }}
            >
              <NotificationsActive />
              Notification Settings
            </Typography>
            <Typography
              variant="body2"
              color="#46639c"
              sx={{ mb: 4, fontWeight: 500 }}
            >
              Manage how you receive notifications
            </Typography>

            <Box
              component="form"
              onSubmit={handleNotificationSave}
              sx={{ display: "flex", flexDirection: "column", gap: 3 }}
            >
              {[
                {
                  label: "Order Updates",
                  description:
                    "Receive notifications for order status changes.",
                  name: "orderUpdates",
                },
                {
                  label: "New Offers",
                  description: "Get notified about new schemes and offers.",
                  name: "newOffers",
                },
                {
                  label: "Chat Messages",
                  description: "Receive notifications for new chat messages.",
                  name: "chatMessages",
                },
              ].map(({ label, description, name }) => (
                <Card
                  key={name}
                  sx={{
                    p: 3,
                    borderRadius: 2,
                    backgroundColor: "#f8fafc",
                    border: "1px solid rgba(0,0,0,0.04)",
                    transition: "all 0.2s",
                    "&:hover": {
                      backgroundColor: "#f1f5f9",
                      borderColor: "#f97316",
                    },
                  }}
                >
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                    }}
                  >
                    <Box>
                      <Typography variant="subtitle1" fontWeight={700} mb={0.5}>
                        {label}
                      </Typography>
                      <Typography variant="body2" color="#46639c">
                        {description}
                      </Typography>
                    </Box>
                    <Switch
                      checked={localNotifications[name]}
                      onChange={handleSwitch(name)}
                      color="primary"
                      disabled
                      sx={{
                        "& .MuiSwitch-switchBase.Mui-checked": {
                          color: "#f97316",
                        },
                        "& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track":
                          {
                            backgroundColor: "#f97316",
                          },
                      }}
                    />
                  </Box>
                </Card>
              ))}
              <Button
                type="submit"
                variant="contained"
                disabled
                sx={{
                  alignSelf: "flex-start",
                  px: 5,
                  py: 1.5,
                  fontWeight: 700,
                  borderRadius: 2,
                  background:
                    "linear-gradient(90deg, #3b82f6 0%, #60a5fa 100%)",
                  textTransform: "none",
                  fontSize: "1rem",
                  boxShadow: "0 4px 12px rgba(59, 130, 246, 0.3)",
                  "&:hover": {
                    background:
                      "linear-gradient(90deg, #2563eb 0%, #3b82f6 100%)",
                    boxShadow: "0 6px 16px rgba(59, 130, 246, 0.4)",
                  },
                }}
                startIcon={<CheckCircle />}
              >
                Save Notifications
              </Button>
            </Box>
          </CardContent>
        </Card>
      </Box>
    </Box>
  );
}
